parameters.responseBody:
={{ JSON.stringify({
  "success": true,
  "leadId": $json.leadId,
  "message": "Your application has been received and is under review. Reference: " + $json.leadId,
  "submittedAt": $json.submittedAt
}) }}

parameters.jsonOutput:
={{ Object.assign({}, $json, {
  "riskLevel": "High Risk",
  "riskReasons": [
    $json.investmentAmount >= 500000 ? 'Investment ≥ $500K' : null,
    $json.previousDenials >= 1 ? 'Prior Denial(s): ' + $json.previousDenials : null,
    ['Iran','Russia','North Korea','Belarus','Cuba','Syria','Venezuela','Myanmar','Sudan','Zimbabwe','Libya','Somalia'].indexOf($json.nationality) >= 0 ? 'High-Risk Nationality: ' + $json.nationality : null
  ].filter(function(r){ return r !== null; }).join(', '),
  "status": "Awaiting Partner Review"
}) }}

