parameters.jsonOutput:
={{ (function() {
  var leadData = $('Set — Tag as High Risk').item.json;
  var raw = ($json.query && $json.query.decision) ? $json.query.decision : ($json.body && $json.body.decision) ? $json.body.decision : '';
  var decision = String(raw).toLowerCase().trim();
  return Object.assign({}, leadData, {
    "partnerDecision": decision || 'unknown',
    "decidedAt": $now.toISO()
  });
})() }}

={{ Object.assign({}, $json, {
